(x, y, t) => {
  const cx = 240, cy = 120;
  const n = (a, b) => (Math.sin(a*1.17+b*0.73)*0.5+Math.sin(a*0.91-b*1.31)*0.3+Math.sin(a*2.03+b*1.47)*0.2);
  const warp1 = n(x*0.012+t*0.15, y*0.012-t*0.12)*20;
  const warp2 = n(x*0.018-t*0.1, y*0.015+t*0.13)*15;
  const warp3 = n(x*0.008+t*0.08, y*0.01-t*0.07)*25;
  const sx = x + warp1 + warp2, sy = y + warp1*0.7 + warp3;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*60, 0.07, 2.2, 1.0],
    [320+Math.cos(t*0.45)*100, 160+Math.sin(t*0.6)*55, 0.09, 1.8, 0.8],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*100, 0.055, 2.5, 1.2],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*65, 0.11, 1.6, 0.9],
    [380+Math.sin(t*0.38+4)*100, 55+Math.cos(t*0.8+2)*75, 0.065, 2.8, 1.1],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.48)*85, 0.08, 2.0, 0.85],
    [60+Math.sin(t*0.6+3)*70, 120+Math.cos(t*0.4+5)*90, 0.1, 1.9, 0.75],
    [400+Math.cos(t*0.33+2)*60, 180+Math.sin(t*0.52+1)*70, 0.075, 2.4, 1.05]
  ];
  let aS = 0, iS = 0, wS = 0;
  for (const [sX, sY, f, sp, wt] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * wt;
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + 1.8) * wt;
    wS += Math.sin(d*f*1.3 - t*sp*0.8 + 3.0) * wt * 0.5;
  }
  const tw = src.reduce((s,v) => s+v[4], 0);
  aS /= tw; iS /= tw; wS /= tw;
  const bg1 = n(sx*0.035+sy*0.02+t*0.7, sx*0.025-sy*0.035+t*0.9);
  const bg2 = n(sx*0.05-sy*0.03+t*1.2, sx*0.04+sy*0.045-t*0.8);
  const bg3 = Math.sin((sx+sy)*0.11+t*2.8)*Math.sin((sx-sy)*0.09-t*2.2)*0.4;
  const bg = bg1*0.4 + bg2*0.3 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3 = Math.sin(dist*0.06-ang*2-t*1.8+1.5);
  const spiral = (sp1+sp2)*0.3 + sp3*0.2;
  const lap = Math.sin(sx*0.22)*Math.sin(sy*0.22) + Math.sin(sx*0.17+sy*0.17+t*0.5)*0.6;
  const diffA = aS - iS*0.6 + bg*0.25 + spiral*0.3;
  const diffB = iS - aS*0.4 - bg*0.15 + wS*0.35 + lap*0.2;
  const feed = Math.sin(t*0.2)*0.1;
  const kill = Math.cos(t*0.15)*0.05;
  const rA = Math.tanh((diffA + feed)*2.5);
  const rB = Math.tanh((diffB + kill)*2.0);
  const pattern = Math.tanh((rA*0.65 - rB*0.35 + Math.sin(rA*rB*4)*0.15)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.16)*Math.sin(sy*0.16) + Math.sin((sx+sy)*0.11+t*0.4)*0.4 + Math.sin(sx*0.23-sy*0.13+t*0.7)*0.2)*1.8)*0.25;
  const micro = Math.sin(sx*0.4+t*1.5)*Math.sin(sy*0.35-t*1.2)*0.1;
  const blend = pattern*0.6 + cell*0.25 + micro;
  const v = blend*0.5+0.5;
  const pal = [
    [5,10,45],[10,30,72],[12,55,95],[18,90,115],[30,135,130],
    [80,170,145],[170,195,110],[220,195,75],[235,165,65],
    [230,120,70],[210,80,75],[180,50,80],[120,25,70],[60,15,55],[5,10,45]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx - i;
  const c0 = pal[i], c1 = pal[i+1];
  const edge = Math.abs(pattern) > 0.65 ? 1.2 : Math.abs(pattern) > 0.4 ? 1.05 : 0.92;
  const glow = Math.max(0, 1.0 - Math.abs(pattern)*0.8)*0.15;
  const lum = 0.85 + Math.sin(pattern*Math.PI*1.2)*0.15 + glow;
  const shimmer = 1.0 + Math.sin(sx*0.3+sy*0.25+t*3)*0.04*Math.abs(pattern);
  const L = lum * edge * shimmer;
  return [
    Math.min(255, (c0[0]+(c1[0]-c0[0])*f)*L)|0,
    Math.min(255, (c0[1]+(c1[1]-c0[1])*f)*L)|0,
    Math.min(255, (c0[2]+(c1[2]-c0[2])*f)*L)|0
  ];
}
